                    system_id="radar",
                    power_state=True,
                    operational_state="yellow",
                ),
            ],
        ),
    ]
    changes = engine._apply_system_effects(opts)
    assert len(changes) == 2
    actions = {c["action"] for c in changes}
    assert actions == {"power_changed", "operational_changed"}

