  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  computed,
  5→  effect,
  6→  ElementRef,
  7→  inject,
  8→  input,
  9→  viewChild,
 10→} from "@angular/core";
 11→import type {
 12→  EventSnapshot,
 13→  IssueSnapshot,
 14→} from "../../core/engine-api.service";
 15→import { DomainService } from "../../core/domain.service";
 16→import { TimelineLaneComponent } from "./timeline-lane.component";
 17→import { computeTimelineItems, computeTimeScale } from "./timeline-utils";
 18→
 19→const DEFAULT_WIDTH_PX = 1200;
 20→
 21→@Component({
 22→  selector: "tfc-event-timeline",
 23→  changeDetection: ChangeDetectionStrategy.OnPush,
 24→  imports: [TimelineLaneComponent],
 25→  template: `
 26→    <div class="timeline-container" #scrollContainer>
 27→      <div class="timeline-track" [style.width.px]="trackWidthPx()">
 28→        <div class="timeline-axis">
 29→          @for (tick of axisTicks(); track tick.ms) {
 30→            <span class="timeline-tick" [style.left.px]="tick.px">
 31→              {{ tick.label }}
 32→            </span>
 33→          }
 34→        </div>
 35→
 36→        <div class="timeline-lane-group">
 37→          <span class="timeline-lane-group__label"
 38→            >{{ domain.term("event") }}s</span
 39→          >
 40→          <tfc-timeline-lane
 41→            [items]="timeline().eventItems"
 42→            [scale]="scale()"
 43→          />
 44→        </div>
 45→
 46→        <div class="timeline-lane-group">
 47→          <span class="timeline-lane-group__label"
 48→            >{{ domain.term("issue") }}s</span
 49→          >
 50→          <tfc-timeline-lane
 51→            [items]="timeline().issueItems"
 52→            [scale]="scale()"
 53→          />
 54→        </div>
 55→
 56→        <div class="timeline-now-marker" [style.left.px]="nowMarkerPx()"></div>
 57→      </div>
 58→    </div>
 59→  `,
 60→  host: { class: "event-timeline" },
 61→})
 62→export class EventTimelineComponent {
 63→  readonly events = input<EventSnapshot[]>([]);
 64→  readonly issues = input<IssueSnapshot[]>([]);
 65→  readonly playTimeMs = input(0);
 66→
 67→  protected readonly domain = inject(DomainService);
 68→  private readonly scrollRef =
 69→    viewChild<ElementRef<HTMLElement>>("scrollContainer");
 70→
 71→  protected readonly timeline = computed(() =>
 72→    computeTimelineItems(this.events(), this.issues(), this.playTimeMs()),
 73→  );
 74→
 75→  protected readonly scale = computed(() => {
 76→    const all = [...this.timeline().eventItems, ...this.timeline().issueItems];
 77→    return computeTimeScale(all, this.playTimeMs(), DEFAULT_WIDTH_PX);
 78→  });
 79→
 80→  protected readonly trackWidthPx = computed(() =>
 81→    Math.max(this.scale().totalMs * this.scale().pxPerMs, DEFAULT_WIDTH_PX),
 82→  );
 83→
 84→  protected readonly nowMarkerPx = computed(
 85→    () => this.playTimeMs() * this.scale().pxPerMs,
 86→  );
 87→
 88→  protected readonly axisTicks = computed(() => {
 89→    const { totalMs, pxPerMs } = this.scale();
 90→    const interval = pickTickInterval(totalMs);
 91→    const ticks: { ms: number; px: number; label: string }[] = [];
 92→    for (let ms = 0; ms <= totalMs; ms += interval) {
 93→      ticks.push({ ms, px: ms * pxPerMs, label: formatTickLabel(ms) });
 94→    }
 95→    return ticks;
 96→  });
 97→
 98→  constructor() {
 99→    effect(() => {
100→      const markerPx = this.nowMarkerPx();
101→      const el = this.scrollRef()?.nativeElement;
102→      if (el) {
103→        const target = markerPx - el.clientWidth * 0.7;
104→        el.scrollLeft = Math.max(0, target);
105→      }
106→    });
107→  }
108→}
109→
110→function pickTickInterval(totalMs: number): number {
111→  if (totalMs <= 120_000) return 10_000;
112→  if (totalMs <= 600_000) return 60_000;
113→  if (totalMs <= 3_600_000) return 300_000;
114→  return 600_000;
115→}
116→
117→function formatTickLabel(ms: number): string {
118→  const totalSeconds = Math.round(ms / 1000);
119→  const minutes = Math.floor(totalSeconds / 60);
120→  const seconds = totalSeconds % 60;
121→  return seconds === 0
122→    ? `${minutes}m`
123→    : `${minutes}:${String(seconds).padStart(2, "0")}`;
124→}
