 34→interface ExerciseState {
 35→  exerciseId: number | null;
 36→  title: string;
 37→  phase: string;
 38→  gameMode: string;
 39→  practiceMode: boolean;
 40→  playTimeMs: number;
 41→  realTimeMs: number;
 42→  speedFactor: number;
 43→  paused: boolean;
 44→  events: EventSnapshot[]; // domain: "injects"
 45→  issues: IssueSnapshot[]; // domain: "defects"
 46→  decisions: ActiveDecision[];
 47→  participants: ParticipantPresence[];
 48→  context: ScenarioContext | null;
 49→  participantId: string;
 50→  playerRole: string;
 51→  playerType: string;
 52→  score: ScoreState | null;
 53→  loading: boolean;
