 57→const initialState: ExerciseState = {
 58→  exerciseId: null,
 59→  title: "",
 60→  phase: "setup",
 61→  gameMode: "classic",
 62→  practiceMode: false,
 63→  playTimeMs: 0,
 64→  realTimeMs: 0,
 65→  speedFactor: 1,
 66→  paused: true,
 67→  events: [],
 68→  issues: [],
 69→  decisions: [],
 70→  participants: [],
 71→  context: null,
 72→  participantId: "",
 73→  playerRole: "player",
 74→  playerType: "advisor",
 75→  score: null,
 76→  loading: false,
 77→  error: null,
 78→};
 79→
 80→export const ExerciseStore = signalStore(
 81→  withState(initialState),
 82→
 83→  withComputed((store) => ({
 84→    rtClock: computed(() => formatTimeMs(store.realTimeMs())),
 85→    ptClock: computed(() => formatTimeMs(store.playTimeMs())),
 86→    activeEvents: computed(() =>
 87→      store.events().filter((e) => e.lifecycle === "running"),
 88→    ), // active injects
 89→    scheduledEvents: computed(() =>
 90→      store.events().filter((e) => e.lifecycle === "scheduled"),
 91→    ), // scheduled injects
 92→    completedEvents: computed(() =>
 93→      store.events().filter((e) => e.lifecycle === "completed"),
 94→    ), // completed injects
 95→    activeIssues: computed(() =>
 96→      store.issues().filter((i) => i.lifecycle === "active"),
 97→    ), // active defects
 98→    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
 99→    decisionCountdownMs: computed(() => {
100→      const decision = store
101→        .decisions()
102→        .find((d) => d.status === "open" && d.timeout_ms > 0);
103→      if (!decision) return null;
104→      const factor = store.speedFactor() || 1;
105→      const openedAtRt = decision.opened_at_pt_ms / factor;
106→      const elapsed = store.realTimeMs() - openedAtRt;
107→      return Math.max(0, decision.timeout_ms - elapsed);
108→    }),
109→    issuesWithCountdown: computed(() => {
110→      const pt = store.playTimeMs();
111→      return store
112→        .issues()
113→        .filter(
114→          (i) =>
115→            i.lifecycle === "active" &&
116→            i.auto_resolve_ms > 0 &&
117→            i.activated_at_pt_ms !== null,
118→        )
119→        .map((i) => {
120→          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
121→          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
122→          return { ...i, remaining_ms: remaining };
123→        });
124→    }),
125→    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
126→    openDecisions: computed(() =>
127→      store.decisions().filter((d) => d.status === "open"),
128→    ),
129→    hasOpenDecision: computed(
130→      () => store.decisions().filter((d) => d.status === "open").length > 0,
131→    ),
132→    connectedParticipants: computed(() =>
133→      store.participants().filter((p) => p.connected),
134→    ),
135→    connectedCount: computed(
136→      () => store.participants().filter((p) => p.connected).length,
137→    ),
138→    isCollaborative: computed(
139→      () => store.gameMode() === "simple_collaborative",
140→    ),
141→    isDecisionMaker: computed(() => store.playerType() === "decision_maker"),
142→    isAllAdvisors: computed(() => store.playerRole() === "all_advisors"),
143→    isPracticeMode: computed(() => store.practiceMode()),
144→    phaseBadgeVariant: computed<"default" | "secondary" | "destructive">(() => {
145→      switch (store.phase()) {
146→        case "running":
147→          return "default";
148→        case "paused":
149→          return "secondary";
150→        case "completed":
151→          return "destructive";
152→        default:
153→          return "secondary";
154→      }
155→    }),
156→  })),
157→
158→  withMethods((store) => ({
159→    setExerciseId(id: number): void {
160→      patchState(store, { exerciseId: id });
161→    },
162→
163→    applySnapshot(snapshot: SnapshotWithScore): void {
164→      patchState(store, {
165→        exerciseId: snapshot.exercise_id,
166→        title: snapshot.title,
167→        phase: snapshot.phase,
168→        playTimeMs: snapshot.time.play_time_ms,
169→        realTimeMs: snapshot.time.real_time_ms,
170→        speedFactor: snapshot.time.factor,
171→        paused: snapshot.time.paused,
172→        events: snapshot.events,
173→        issues: snapshot.issues,
174→        decisions: snapshot.decisions ?? store.decisions(),
175→        score: snapshot.score
176→          ? {
177→              totalScore: snapshot.score.total_score,
178→              penaltyMs: snapshot.score.penalty_ms,
179→              turnNumber: snapshot.score.turn_number,
180→              nextDecisionTimeMs: snapshot.score.next_decision_time_ms,
181→            }
182→          : store.score(),
183→        loading: false,
184→        error: null,
185→      });
186→    },
187→
188→    applyTimeUpdate(time: TimeSnapshot): void {
189→      patchState(store, {
190→        playTimeMs: time.play_time_ms,
191→        realTimeMs: time.real_time_ms,
192→        speedFactor: time.factor,
193→        paused: time.paused,
194→      });
195→    },
196→
197→    /** Advance clocks locally by wall-clock delta (call from a setInterval). */
198→    tick(wallDeltaMs: number): void {
199→      if (store.paused()) return;
200→      const factor = store.speedFactor();
201→      patchState(store, {
202→        realTimeMs: store.realTimeMs() + wallDeltaMs,
203→        playTimeMs: store.playTimeMs() + wallDeltaMs * factor,
204→      });
205→    },
206→
207→    applyPhaseChange(phase: string): void {
208→      patchState(store, { phase });
209→    },
210→
211→    updateEvent(eventId: string, lifecycle: string): void {
212→      const events = store
213→        .events()
214→        .map((e) => (e.id === eventId ? { ...e, lifecycle } : e));
215→      patchState(store, { events });
216→    },
217→
218→    updateIssue(issueId: string, lifecycle: string, released?: boolean): void {
219→      const issues = store
220→        .issues()
221→        .map((i) =>
222→          i.id === issueId
223→            ? { ...i, lifecycle, released: released ?? i.released }
224→            : i,
225→        );
226→      patchState(store, { issues });
227→    },
228→
229→    setLoading(loading: boolean): void {
230→      patchState(store, { loading });
231→    },
232→
233→    setError(error: string): void {
234→      patchState(store, { error, loading: false });
235→    },
236→
237→    applyDecisions(decisions: ActiveDecision[]): void {
238→      patchState(store, { decisions });
239→    },
240→
241→    setContext(ctx: ScenarioContext): void {
242→      patchState(store, { context: ctx });
243→    },
244→
245→    setParticipantId(id: string): void {
246→      patchState(store, { participantId: id });
247→    },
248→
249→    setPlayerRole(role: string): void {
250→      patchState(store, { playerRole: role });
251→    },
252→
253→    closeDecision(decisionId: string): void {
254→      const decisions = store
255→        .decisions()
256→        .map((d) => (d.id === decisionId ? { ...d, status: "closed" } : d));
257→      patchState(store, { decisions });
258→    },
259→
260→    updatePresence(participants: ParticipantPresence[]): void {
261→      patchState(store, { participants });
262→    },
263→
264→    setGameMode(mode: string): void {
265→      patchState(store, { gameMode: mode });
266→    },
267→
268→    setPracticeMode(practice: boolean): void {
269→      patchState(store, { practiceMode: practice });
270→    },
271→
272→    setPlayerType(playerType: string): void {
273→      patchState(store, { playerType });
274→    },
275→
276→    setSpeedFactor(factor: number): void {
277→      patchState(store, { speedFactor: factor });
278→    },
279→
280→    applyScoreChange(change: Pick<ScoreChange, "total_score" | "penalty_ms" | "next_decision_time_ms" | "turn_number">): void {
281→      patchState(store, {
282→        score: {
283→          totalScore: change.total_score,
284→          penaltyMs: change.penalty_ms,
285→          nextDecisionTimeMs: change.next_decision_time_ms,
286→          turnNumber: change.turn_number,
287→        },
288→      });
289→    },
290→
291→    applyRecommendation(
292→      decisionId: string,
293→      participantId: string,
294→      optionId: string,
295→    ): void {
296→      const decisions = store.decisions().map((d) =>
297→        d.id === decisionId
298→          ? {
299→              ...d,
300→              recommendations: {
301→                ...d.recommendations,
302→                [participantId]: optionId,
303→              },
304→            }
305→          : d,
306→      );
307→      patchState(store, { decisions });
308→    },
309→  })),
310→);
