185→export class ReviewView implements OnInit, OnDestroy {
186→  private readonly route = inject(ActivatedRoute);
187→  private readonly auditApi = inject(AuditApiService);
188→
189→  protected readonly auditLog = signal<AuditEntry[]>([]);
190→  protected readonly replayIndex = signal(0);
191→  protected readonly playing = signal(false);
192→  protected readonly playbackSpeed = signal(1);
193→  private playTimer: ReturnType<typeof setInterval> | null = null;
194→
195→  protected readonly sortedLog = computed(() =>
196→    [...this.auditLog()].sort((a, b) => a.play_time_ms - b.play_time_ms),
197→  );
198→
199→  protected readonly visibleEntries = computed(() =>
200→    this.sortedLog().slice(0, this.replayIndex()),
201→  );
202→
203→  protected readonly currentEntry = computed(() => {
204→    const idx = this.replayIndex();
205→    const log = this.sortedLog();
206→    return idx > 0 ? log[idx - 1] : null;
207→  });
208→
209→  protected readonly progressPercent = computed(() => {
210→    const total = this.sortedLog().length;
211→    return total === 0 ? 0 : (this.replayIndex() / total) * 100;
212→  });
213→
214→  protected eventEntries = computed(() =>
215→    this.visibleEntries().filter((e) => e.entry_type === "event_change"),
216→  );
217→
218→  protected decisionEntries = computed(() =>
219→    this.visibleEntries().filter((e) => e.entry_type === "decision"),
220→  );
221→
222→  protected formatTime = formatTimeMs;
223→
224→  ngOnInit(): void {
225→    const params = this.route.snapshot.queryParams;
226→    const exerciseId = Number(params["exerciseId"] ?? 1);
227→    this.auditApi.getLog(exerciseId).subscribe({
228→      next: (entries) => this.auditLog.set(entries),
229→    });
230→  }
231→
232→  ngOnDestroy(): void {
233→    this.stopPlayback();
234→  }
235→
236→  protected isHighlighted(entry: AuditEntry): boolean {
237→    const current = this.currentEntry();
238→    return current !== null && entry.id === current.id;
239→  }
240→
241→  protected stepForward(): void {
242→    if (this.replayIndex() < this.sortedLog().length) {
243→      this.replayIndex.update((i) => i + 1);
244→    }
245→  }
246→
247→  protected stepBack(): void {
248→    if (this.replayIndex() > 0) {
249→      this.replayIndex.update((i) => i - 1);
250→    }
251→  }
252→
253→  protected resetReplay(): void {
254→    this.stopPlayback();
255→    this.replayIndex.set(0);
256→  }
257→
258→  protected togglePlay(): void {
259→    if (this.playing()) {
260→      this.stopPlayback();
261→    } else {
262→      this.startPlayback();
263→    }
264→  }
265→
266→  protected onSpeedChange(event: Event): void {
267→    const target = event.target;
268→    if (!(target instanceof HTMLSelectElement)) return;
269→    const speed = parseFloat(target.value);
270→    this.playbackSpeed.set(speed);
271→    if (this.playing()) {
272→      this.stopPlayback();
273→      this.startPlayback();
274→    }
275→  }
276→
277→  private startPlayback(): void {
278→    this.playing.set(true);
279→    const interval = 1000 / this.playbackSpeed();
280→    this.playTimer = setInterval(() => {
281→      if (this.replayIndex() >= this.sortedLog().length) {
282→        this.stopPlayback();
283→        return;
284→      }
285→      this.stepForward();
286→    }, interval);
287→  }
288→
289→  private stopPlayback(): void {
290→    this.playing.set(false);
291→    if (this.playTimer) {
292→      clearInterval(this.playTimer);
293→      this.playTimer = null;
294→    }
295→  }
296→}
