198→export class WaitingRoomView implements OnInit, OnDestroy {
199→  private readonly route = inject(ActivatedRoute);
200→  private readonly router = inject(Router);
201→  private readonly http = inject(HttpClient);
202→  private readonly api = inject(WaitingRoomApiService);
203→  private readonly ws = inject(ExerciseWsService);
204→  private readonly exerciseApi = inject(ExerciseApiService);
205→  private readonly scenarioApi = inject(ScenarioApiService);
206→  private sub: Subscription | null = null;
207→
208→  protected readonly browseMode = signal(false);
209→  protected readonly joinableExercises = signal<JoinableExercise[]>([]);
210→  protected readonly exerciseId = signal(0);
211→  protected readonly participantId = signal("");
212→  protected readonly participants = signal<ParticipantResponse[]>([]);
213→  protected readonly gameMode = signal("classic");
214→  protected readonly playerCountMode = signal<PlayerCountMode>("full");
215→  protected readonly scenarioRoles = signal<RoleDef[]>([]);
216→  protected readonly requiresGm = signal(false);
217→  protected readonly displayName = signal("");
218→  protected readonly joining = signal(false);
219→
220→  protected readonly isSimpleCollaborative = computed(
221→    () => this.gameMode() === "simple_collaborative",
222→  );
223→  protected readonly twoPlayerMode = computed(
224→    () => this.playerCountMode() === "two_player",
225→  );
226→  protected readonly practiceMode = computed(
227→    () => this.playerCountMode() === "practice",
228→  );
229→  protected readonly activeModeName = computed(() => {
230→    const mode = this.playerCountMode();
231→    return mode === "practice" ? "Practice (Solo)" :
232→           mode === "two_player" ? "2 Players" : "Full Team";
233→  });
234→
235→  protected readonly maxSlots = computed(() => {
236→    if (this.practiceMode()) return 1;
237→    if (this.twoPlayerMode()) return 2;
238→    const roles = this.scenarioRoles();
239→    return roles.length + (this.requiresGm() ? 1 : 0);
240→  });
241→
242→  protected readonly readinessPercent = computed(() => {
243→    const max = this.maxSlots();
244→    return max > 0 ? (this.participants().length / max) * 100 : 0;
245→  });
246→
247→  protected readonly canStart = computed(() => {
248→    const roles = this.scenarioRoles();
249→    if (!roles.length) return false;
250→    if (this.practiceMode()) return this.participants().length === 1;
251→    if (this.twoPlayerMode()) {
252→      const pRoles = this.participants().map((p) => p.role);
253→      return (
254→        this.participants().length === 2 &&
255→        pRoles.includes("decision_maker") &&
256→        pRoles.includes("all_advisors")
257→      );
258→    }
259→    return this.participants().length >= this.maxSlots();
260→  });
261→
262→  ngOnInit(): void {
263→    const params = this.route.snapshot.queryParams;
264→    const eId = Number(params["exerciseId"] ?? 0);
265→    const pId = String(params["participantId"] ?? "");
266→    const browse = params["browse"] === "true";
267→
268→    const pcm = params["playerCountMode"] as PlayerCountMode | undefined;
269→    if (pcm) {
270→      this.playerCountMode.set(pcm);
271→    }
272→
273→    if (browse) {
274→      this.browseMode.set(true);
275→      this.loadJoinableExercises();
276→    }
277→
278→    if (eId) {
279→      this.initExercise(eId, pId);
280→    }
281→  }
282→
283→  ngOnDestroy(): void {
284→    this.ws.disconnect();
285→    this.sub?.unsubscribe();
286→  }
287→
288→  protected selectExercise(lobby: JoinableExercise): void {
289→    this.ws.disconnect();
290→    this.sub?.unsubscribe();
291→    this.participantId.set("");
292→    this.participants.set([]);
293→    this.scenarioRoles.set([]);
294→    this.initExercise(lobby.exercise.id, "");
295→  }
296→
297→  protected onPlayerCountMode(mode: PlayerCountMode): void {
298→    this.playerCountMode.set(mode);
299→  }
300→
301→  protected onJoin(): void {
302→    const name = this.displayName().trim();
303→    if (!name) return;
304→    this.joining.set(true);
305→    this.api.join(this.exerciseId(), name, "player").subscribe({
306→      next: (p) => {
307→        this.participantId.set(p.id);
308→        this.joining.set(false);
309→      },
310→      error: () => this.joining.set(false),
311→    });
312→  }
313→
314→  protected onClaimRole(roleId: string): void {
315→    this.api
316→      .updateRole(this.exerciseId(), this.participantId(), roleId)
317→      .subscribe();
318→  }
319→
320→  protected onTwoPlayerRoleChange(ev: { targetId: string; roleId: string }): void {
321→    this.api.updateRole(this.exerciseId(), ev.targetId, ev.roleId).subscribe();
322→  }
323→
324→  protected onLeave(): void {
325→    this.api.leave(this.exerciseId(), this.participantId()).subscribe({
326→      next: () => this.router.navigate(["/home"]),
327→      error: () => this.router.navigate(["/home"]),
328→    });
329→  }
330→
331→  protected onBackHome(): void {
332→    this.router.navigate(["/home"]);
333→  }
334→
335→  protected onStartExercise(): void {
336→    const me = this.participants().find((p) => p.id === this.participantId());
337→    const role = me?.role ?? "player";
338→    if (this.isSimpleCollaborative()) {
339→      this.router.navigate(["/player"], {
340→        queryParams: {
341→          exerciseId: this.exerciseId(),
342→          participantId: this.participantId(),
343→          role,
344→          gameMode: "simple_collaborative",
345→          practiceMode: this.practiceMode(),
346→        },
347→      });
348→      return;
349→    }
350→    const isGm = role === "game-master";
351→    this.router.navigate([isGm ? "/gm" : "/player"], {
352→      queryParams: {
353→        exerciseId: this.exerciseId(),
354→        participantId: this.participantId(),
355→        role,
356→      },
357→    });
358→  }
359→
360→  private initExercise(exerciseId: number, participantId: string): void {
361→    this.exerciseId.set(exerciseId);
362→    this.participantId.set(participantId);
363→    this.ws.connect(exerciseId, "player");
364→    this.sub = this.ws.messages$.subscribe((msg) => {
365→      if (msg.type === "waiting_room_update") {
366→        if (msg.participants) this.participants.set(msg.participants);
367→      }
368→    });
369→    this.api.listParticipants(exerciseId).subscribe({
370→      next: (res) => this.participants.set(res.participants),
371→    });
372→    this.loadScenarioRoles(exerciseId);
373→  }
374→
375→  private loadJoinableExercises(): void {
376→    this.http
377→      .get<JoinableExercise[]>(
378→        `${environment.apiBaseUrl}/api/exercises/joinable`,
379→      )
380→      .subscribe({
381→        next: (data) => this.joinableExercises.set(data),
382→        error: () => this.joinableExercises.set([]),
383→      });
384→  }
385→
386→  private loadScenarioRoles(exerciseId: number): void {
387→    this.exerciseApi.get(exerciseId).subscribe({
388→      next: (exercise) => {
389→        this.gameMode.set(exercise.game_mode);
390→        this.requiresGm.set(exercise.game_mode === "classic");
391→        if (exercise.scenario_id) {
392→          this.scenarioApi.get(exercise.scenario_id).subscribe({
393→            next: (scenario) =>
394→              this.scenarioRoles.set(scenario.content?.roles ?? []),
395→          });
396→        }
397→      },
398→    });
399→  }
400→}
