 86→export class DecisionPanelComponent implements AfterViewInit {
 87→  private readonly anim = inject(AnimationService);
 88→  private readonly el = inject(ElementRef);
 89→  readonly title = input.required<string>();
 90→  readonly description = input<string>("");
 91→  readonly questionType = input.required<string>();
 92→  readonly options = input<DecisionOption[]>([]);
 93→  readonly closed = output();
 94→  readonly submitted = output<{
 95→    selectedOptions: string[];
 96→    freeText: string;
 97→  }>();
 98→
 99→  protected readonly selectedOptions = signal<string[]>([]);
100→  protected readonly freeText = signal("");
101→
102→  ngAfterViewInit(): void {
103→    const options = this.el.nativeElement.querySelectorAll(
104→      ".decision-panel__option",
105→    );
106→    this.anim.staggerIn(options);
107→  }
108→
109→  protected canSubmit(): boolean {
110→    if (this.questionType() === "free_text")
111→      return this.freeText().trim().length > 0;
112→    return this.selectedOptions().length > 0;
113→  }
114→
115→  protected selectSingle(id: string): void {
116→    this.selectedOptions.set([id]);
117→  }
118→
119→  protected toggleMulti(id: string): void {
120→    const current = this.selectedOptions();
121→    if (current.includes(id)) {
122→      this.selectedOptions.set(current.filter((o) => o !== id));
123→    } else {
124→      this.selectedOptions.set([...current, id]);
125→    }
126→  }
127→
128→  protected onTextInput(event: Event): void {
129→    const target = event.target;
130→    if (target instanceof HTMLTextAreaElement) {
131→      this.freeText.set(target.value);
132→    }
133→  }
134→
135→  protected onSubmit(): void {
136→    this.submitted.emit({
137→      selectedOptions: this.selectedOptions(),
138→      freeText: this.freeText(),
139→    });
140→  }
141→}
