 19→
 20→export interface ParticipantPresence {
 21→  id: string;
 22→  display_name: string;
 23→  role: string | null;
 24→  connected: boolean;
 25→}
 26→
 27→interface ScoreState {
 28→  totalScore: number;
 29→  turnNumber: number;
 30→  nextDecisionTimeMs: number;
