 52→export class PlayerView implements OnInit, OnDestroy {
 53→  protected readonly store = inject(ExerciseStore);
 54→  protected readonly domain = inject(DomainService);
 55→  private readonly api = inject(EngineApiService);
 56→  private readonly decisionApi = inject(DecisionApiService);
 57→  private readonly ws = inject(ExerciseWsService);
 58→  private readonly router = inject(Router);
 59→  private readonly route = inject(ActivatedRoute);
 60→  protected readonly roleLabel = signal("Advisor");
 61→  protected readonly beginningExercise = signal(false);
 62→  private readonly exerciseId = signal(1);
 63→  private readonly participantId = signal("");
 64→  private readonly tick = inject(TickService);
 65→  private snapshotLoaded = false;
 66→  private sub: Subscription | null = null;
 67→  private connSub: Subscription | null = null;
 68→
 69→  protected readonly activeDecisions = computed(() => {
 70→    const role = this.store.playerRole();
 71→    return this.store.openDecisions().filter((d) => {
 72→      if (!d.target_roles || d.target_roles.length === 0) return true;
 73→      if (role === "all_roles" || role === "all_advisors" || role === "solo_player") return true;
 74→      return d.target_roles.includes(role);
 75→    });
 76→  });
 77→
 78→  protected readonly isMultiRole = computed(() => {
 79→    const role = this.store.playerRole();
 80→    return role === "all_advisors" || role === "solo_player" || role === "all_roles";
 81→  });
 82→
 83→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 84→
 85→  protected readonly currentTurnEvent = computed(() => {
 86→    const decisions = this.activeDecisions();
 87→    if (decisions.length === 0) return null;
 88→    const decision = decisions[0];
 89→    if (!decision.event_id) return null;
 90→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
 91→  });
 92→
 93→  protected readonly roleCards = computed(() => {
 94→    const allRoles = this.store.context()?.roles ?? [];
 95→    const event = this.currentTurnEvent();
 96→    const decision = this.activeDecisions()[0] ?? null;
 97→    const role = this.store.playerRole();
 98→    const multiRole = this.isMultiRole();
 99→    const showDecisionMaker =
100→      role === "all_roles" || role === "solo_player" || this.store.isPracticeMode();
101→    // Single-role players see only their own role card
102→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
103→    return buildRoleCards(roles, event, decision, this.submittedRoles(), showDecisionMaker);
104→  });
105→
106→  private _lastDecisionId: string | null = null;
107→  private readonly resetSubmittedRolesEffect = effect(() => {
108→    const id = this.activeDecisions()[0]?.id ?? null;
109→    // Only reset when the decision ID actually changes (not on every WS push)
110→    if (id && id !== this._lastDecisionId) {
111→      this._lastDecisionId = id;
112→      this.submittedRoles.set(new Set());
113→    }
114→  });
115→
116→  ngOnInit(): void {
117→    const params = this.route.snapshot.queryParams;
118→    const id = Number(params["exerciseId"] ?? 1);
119→    const pId = String(params["participantId"] ?? "");
120→    const role = String(params["role"] ?? "player");
121→    const gameMode = String(params["gameMode"] ?? "");
122→    this.exerciseId.set(id);
123→    this.participantId.set(pId);
124→    this.store.setParticipantId(pId);
125→    this.store.setPlayerRole(role);
126→    if (gameMode) {
127→      this.store.setGameMode(gameMode);
128→    }
129→    const practiceMode = params["practiceMode"] === "true";
130→    this.store.setPracticeMode(practiceMode);
131→    this.ws.connect(id, "player", pId || undefined);
132→    this.sub = this.ws.messages$.subscribe((msg) =>
133→      handlePlayerWsMessage(msg, this.store, () => this.onExerciseStopped()),
134→    );
135→    this.loadSnapshot(id);
136→    this.decisionApi.getContext(id).subscribe({
137→      next: (ctx) =>
138→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
139→      error: () => {},
140→    });
141→    this.decisionApi.getEngineDecisions(id).subscribe({
142→      next: (decisions) => this.store.applyDecisions(decisions),
143→      error: () => {},
144→    });
145→    this.connSub = this.ws.connected$.subscribe((connected) => {
146→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
147→    });
148→    this.tick.start(this.store);
149→  }
150→
151→  private loadSnapshot(exerciseId: number): void {
152→    this.api.snapshot(exerciseId).subscribe({
153→      next: (snap) => {
154→        this.snapshotLoaded = true;
155→        this.store.applySnapshot(snap);
156→      },
157→      error: () => this.store.setError("Failed to load snapshot"),
158→    });
159→  }
160→
161→  protected onBeginExercise(): void {
162→    this.beginningExercise.set(true);
163→    this.api.begin(this.exerciseId()).subscribe({
164→      next: (change) => {
165→        this.store.applyPhaseChange(change.phase);
166→        this.store.applyTimeUpdate(change.time);
167→        this.beginningExercise.set(false);
168→      },
169→      error: () => {
170→        this.store.setError("Failed to begin exercise");
171→        this.beginningExercise.set(false);
172→      },
173→    });
174→  }
175→
176→  protected onStop(): void {
177→    this.api.stop(this.exerciseId()).subscribe({
178→      next: () => this.onExerciseStopped(),
179→    });
180→  }
181→
182→  private onExerciseStopped(): void {
183→    this.ws.disconnect();
184→    this.router.navigate(["/"]);
185→  }
186→
187→  ngOnDestroy(): void {
188→    this.tick.stop();
189→    this.ws.disconnect();
190→    this.sub?.unsubscribe();
191→    this.connSub?.unsubscribe();
192→  }
193→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
194→    const decision = this.activeDecisions()[0];
195→    if (!decision) return;
196→    const role = this.store.context()?.roles?.find(
197→      (r) => r.id === submission.roleId,
198→    );
199→    if (role?.player_type === "decision_maker") {
200→      submitDecision(
201→        this.decisionApi,
202→        this.store,
203→        this.exerciseId(),
204→        decision,
205→        this.participantId(),
206→        submission,
207→      );
208→    } else {
209→      submitRoleRecommendation(
210→        this.decisionApi,
211→        this.exerciseId(),
212→        decision,
213→        this.participantId(),
214→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
215→      );
216→    }
217→    const updated = new Set(this.submittedRoles());
218→    updated.add(submission.roleId);
219→    this.submittedRoles.set(updated);
220→  }
221→}
